//! Persistent bit-partitioned vector trie (branching factor 32) + tail buffer.
use std::rc::Rc;

pub const BITS: u32 = 5;
pub const WIDTH: usize = 1 << BITS; // 32
pub const MASK: usize = WIDTH - 1;  // 31

enum Node<T> {
    Branch(Vec<Rc<Node<T>>>), // 1..=32 children, LEFT-PACKED (no gaps)
    Leaf(Vec<T>),             // exactly 32 elements (tree leaves are always full)
}

impl<T> Node<T> {
    fn children(&self) -> &[Rc<Node<T>>] {
        match self {
            Node::Branch(c) => c,
            Node::Leaf(_) => unreachable!("descended into a leaf"),
        }
    }
    fn leaf(&self) -> &[T] {
        match self {
            Node::Leaf(v) => v,
            Node::Branch(_) => unreachable!("expected leaf"),
        }
    }
}

pub struct PVec<T> {
    cnt: usize,           // total element count
    shift: u32,           // >= BITS ; root is a Branch at this level
    root: Rc<Node<T>>,    // holds exactly tail_off = cnt - tail.len() elements
    tail: Rc<Vec<T>>,     // 0..=32 ; len 0 only when cnt == 0
}

impl<T> Clone for PVec<T> {
    fn clone(&self) -> Self {
        PVec { cnt: self.cnt, shift: self.shift,
               root: Rc::clone(&self.root), tail: Rc::clone(&self.tail) }
    }
}

impl<T> Default for PVec<T> {
    fn default() -> Self { Self::new() }
}

impl<T> PVec<T> {
    pub fn new() -> Self {
        PVec { cnt: 0, shift: BITS, root: Rc::new(Node::Branch(Vec::new())),
               tail: Rc::new(Vec::new()) }
    }
    pub fn len(&self) -> usize { self.cnt }
    pub fn is_empty(&self) -> bool { self.cnt == 0 }

    /// tail_off: index of first element living in the tail. Always a multiple of 32.
    fn tail_off(&self) -> usize { self.cnt - self.tail.len() }

    /// number of leaves stored in the tree
    fn leaf_cnt(&self) -> usize { self.tail_off() >> BITS }

    pub fn get(&self, i: usize) -> Option<&T> {
        if i >= self.cnt { return None; }
        Some(self.index_unchecked(i))
    }

    fn index_unchecked(&self, i: usize) -> &T {
        let chunk = self.chunk_for(i);
        &chunk[i & MASK]
    }

    /// the 32-wide chunk containing index i (tree leaf, or the tail)
    fn chunk_for(&self, i: usize) -> &[T] {
        debug_assert!(i < self.cnt);
        if i >= self.tail_off() { return &self.tail; }
        let mut node: &Node<T> = &self.root;
        let mut s = self.shift;
        while s > 0 {
            node = &node.children()[(i >> s) & MASK];
            s -= BITS;
        }
        node.leaf()
    }
}

impl<T> std::ops::Index<usize> for PVec<T> {
    type Output = T;
    fn index(&self, i: usize) -> &T {
        self.get(i).expect("PVec index out of bounds")
    }
}

// ---------- push_back ----------

/// Build a chain of single-child branches from level `shift` down to `leaf`.
/// Returns a node living at level `shift` (shift == 0 -> the leaf itself).
fn new_path<T>(shift: u32, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
    if shift == 0 { leaf } else { Rc::new(Node::Branch(vec![new_path(shift - BITS, leaf)])) }
}

/// Insert `leaf` as leaf number `m` (global, 0-based) into the branch `node`
/// living at level `shift`. Requires m < (1 << shift) (i.e. subtree has room).
fn push_tail<T>(shift: u32, node: &Node<T>, m: usize, leaf: Rc<Node<T>>) -> Rc<Node<T>> {
    let sub = (m >> (shift - BITS)) & MASK;
    let mut ch: Vec<Rc<Node<T>>> = node.children().to_vec();
    debug_assert!(sub <= ch.len(), "left-packed invariant violated");
    if sub == ch.len() {
        ch.push(new_path(shift - BITS, leaf));
    } else {
        debug_assert!(shift > BITS);
        ch[sub] = push_tail(shift - BITS, &ch[sub], m, leaf);
    }
    Rc::new(Node::Branch(ch))
}

impl<T: Clone> PVec<T> {
    pub fn push_back(&self, x: T) -> Self {
        // Case 1: room in the tail.
        if self.tail.len() < WIDTH {
            let mut t = Vec::with_capacity(WIDTH);
            t.extend_from_slice_clone(&self.tail);
            t.push(x);
            return PVec { cnt: self.cnt + 1, shift: self.shift,
                          root: Rc::clone(&self.root), tail: Rc::new(t) };
        }
        // Case 2: tail is full (32) -> flush it into the tree as leaf number m.
        let m = self.leaf_cnt();
        let leaf = Rc::new(Node::Leaf((*self.tail).clone()));
        let (root, shift) = if m >= (1usize << self.shift) {
            // tree is exactly full: grow one level
            (Rc::new(Node::Branch(vec![Rc::clone(&self.root),
                                       new_path(self.shift, leaf)])),
             self.shift + BITS)
        } else {
            (push_tail(self.shift, &self.root, m, leaf), self.shift)
        };
        let mut t = Vec::with_capacity(WIDTH);
        t.push(x);
        PVec { cnt: self.cnt + 1, shift, root, tail: Rc::new(t) }
    }
}

// tiny helper so we don't need T: Copy
trait ExtendClone<T> { fn extend_from_slice_clone(&mut self, s: &[T]); }
impl<T: Clone> ExtendClone<T> for Vec<T> {
    fn extend_from_slice_clone(&mut self, s: &[T]) {
        for x in s { self.push(x.clone()); }
    }
}

// ---------- iteration: O(n) total ----------

pub struct Iter<'a, T> {
    chunks: Vec<&'a [T]>, // every tree leaf in order, then the tail if non-empty
    ci: usize,
    ei: usize,
    left: usize,
}

fn collect_leaves<'a, T>(n: &'a Node<T>, out: &mut Vec<&'a [T]>) {
    match n {
        Node::Leaf(v) => out.push(v),
        Node::Branch(ch) => { for c in ch { collect_leaves(c, out) } }
    }
}

impl<T> PVec<T> {
    pub fn iter(&self) -> Iter<'_, T> {
        let mut chunks = Vec::with_capacity(self.leaf_cnt() + 1);
        collect_leaves(&self.root, &mut chunks);
        debug_assert_eq!(chunks.len(), self.leaf_cnt());
        debug_assert!(chunks.iter().all(|c| c.len() == WIDTH));
        if !self.tail.is_empty() { chunks.push(&self.tail); }
        Iter { chunks, ci: 0, ei: 0, left: self.cnt }
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;
    fn next(&mut self) -> Option<&'a T> {
        while self.ci < self.chunks.len() {
            let c = self.chunks[self.ci];
            if self.ei < c.len() {
                let r = &c[self.ei];
                self.ei += 1;
                self.left -= 1;
                return Some(r);
            }
            self.ci += 1;
            self.ei = 0;
        }
        None
    }
    fn size_hint(&self) -> (usize, Option<usize>) { (self.left, Some(self.left)) }
}
impl<'a, T> ExactSizeIterator for Iter<'a, T> {}

impl<'a, T> IntoIterator for &'a PVec<T> {
    type Item = &'a T;
    type IntoIter = Iter<'a, T>;
    fn into_iter(self) -> Iter<'a, T> { self.iter() }
}

impl<T: Clone> std::iter::FromIterator<T> for PVec<T> {
    fn from_iter<I: IntoIterator<Item = T>>(it: I) -> Self {
        let mut v = PVec::new();
        for x in it { v = v.push_back(x); }
        v
    }
}

// ---------- structural audit (used by tests) ----------
impl<T> PVec<T> {
    /// Full invariant check. Returns Err(msg) on violation.
    pub fn audit(&self) -> Result<(), String> {
        if self.shift < BITS || self.shift % BITS != 0 {
            return Err(format!("bad shift {}", self.shift));
        }
        if self.tail.len() > WIDTH { return Err("tail too long".into()); }
        if self.cnt == 0 && !self.tail.is_empty() { return Err("empty but tail".into()); }
        if self.cnt > 0 && self.tail.is_empty() { return Err("non-empty but empty tail".into()); }
        let toff = self.tail_off();
        if toff % WIDTH != 0 { return Err(format!("tail_off {} not mult of 32", toff)); }
        if self.cnt > 0 && toff != ((self.cnt - 1) >> BITS) << BITS {
            return Err("tail_off != ((cnt-1)>>5)<<5".into());
        }
        let m = self.leaf_cnt();
        if m > (1usize << self.shift) {
            return Err(format!("leaf_cnt {} exceeds capacity {}", m, 1usize << self.shift));
        }
        // minimality: shift must be the smallest level that can hold m leaves
        if self.shift > BITS && m <= (1usize << (self.shift - BITS)) {
            return Err(format!("shift {} not minimal for {} leaves", self.shift, m));
        }
        // recursive structure: left-packed, leaves full, depth uniform
        fn walk<T>(n: &Node<T>, shift: u32, want: usize) -> Result<usize, String> {
            match n {
                Node::Leaf(v) => {
                    if shift != 0 { return Err("leaf at wrong level".into()); }
                    if v.len() != WIDTH { return Err(format!("leaf len {}", v.len())); }
                    Ok(1)
                }
                Node::Branch(ch) => {
                    if shift == 0 { return Err("branch at level 0".into()); }
                    if ch.len() > WIDTH { return Err("branch too wide".into()); }
                    if ch.is_empty() && want != 0 { return Err("empty branch".into()); }
                    let cap = 1usize << (shift - BITS); // leaves per child
                    let mut seen = 0usize;
                    for (i, c) in ch.iter().enumerate() {
                        let expect = if want - seen >= cap { cap } else { want - seen };
                        let got = walk(c, shift - BITS, expect)?;
                        if i + 1 < ch.len() && got != cap {
                            return Err("interior child not full (gap)".into());
                        }
                        seen += got;
                    }
                    if seen != want { return Err(format!("subtree has {} leaves, want {}", seen, want)); }
                    Ok(seen)
                }
            }
        }
        walk(&self.root, self.shift, m)?;
        Ok(())
    }
    pub fn debug_shape(&self) -> (usize, u32, usize, usize) {
        (self.cnt, self.shift, self.leaf_cnt(), self.tail.len())
    }
}
