// stoi emulation
fn stoi(s: &str) -> Result<i32, &'static str> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && (b[i] as char).is_whitespace() { i += 1; }
    let neg = if i < b.len() && (b[i] == b'-' || b[i] == b'+') { let n = b[i] == b'-'; i += 1; n } else { false };
    let start = i;
    let mut acc: i64 = 0;
