        i += 1;
    }
    if i == start { return Err("invalid_argument"); }
    let val = if neg { -acc } else { acc };
    if over || val > i32::MAX as i64 || val < i32::MIN as i64 { return Err("out_of_range"); }
    Ok(val as i32)
