static BYTES: AtomicUsize = AtomicUsize::new(0);
struct C;
unsafe impl GlobalAlloc for C {
  unsafe fn alloc(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);BYTES.fetch_add(l.size(),Relaxed);System.alloc(l)}
  unsafe fn dealloc(&self,p:*mut u8,l:Layout){BYTES.fetch_sub(l.size(),Relaxed);System.dealloc(p,l)}
}
#[global_allocator] static A: C = C;
