// Option B: leaves-only flat spine of Rc chunks + tail
#[derive(Clone)] struct FlatVec<T>{ spine: Rc<Vec<Rc<Vec<T>>>>, tail: Rc<Vec<T>>, cnt: usize }
impl<T:Clone> FlatVec<T>{
  fn new()->Self{FlatVec{spine:Rc::new(Vec::new()),tail:Rc::new(Vec::new()),cnt:0}}
  fn push_back(&self,x:T)->Self{
    if self.tail.len()<32 { let mut t=(*self.tail).clone(); t.push(x);
      return FlatVec{spine:Rc::clone(&self.spine),tail:Rc::new(t),cnt:self.cnt+1}; }
    let mut s=(*self.spine).clone();           // <-- O(n/32) COPY on every flush
    s.push(Rc::clone(&self.tail));
    FlatVec{spine:Rc::new(s),tail:Rc::new(vec![x]),cnt:self.cnt+1}
  }
  fn get(&self,i:usize)->&T{ if i>=self.cnt-self.tail.len(){&self.tail[i&31]} else {&self.spine[i>>5][i&31]} }
}
fn main(){ for n in [100_000usize,400_000,1_600_000]{
  let t=Instant::now(); let mut v=FlatVec::new(); for i in 0..n{v=v.push_back(i as i64);}
  let d=t.elapsed(); println!("FlatVec n={:>9} build={:>10.2?} ({:.1} ns/push) last={}",n,d,d.as_nanos() as f64/n as f64,v.get(n-1));}}
EOF
